"before_switch" | 
/**  Taken before a profile and its state folder are removed. */
"before_delete" | 
/**  Taken before another profile's data replaces this profile's data. */
"before_copy" | 
/**  Taken by a restore, so the restore itself can be undone. */
"before_restore";

